"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["20147"],{80344(a){a.exports=JSON.parse('{"id":"FIN-915","slug":"historical-volatility","term":"Historical Volatility","also_known_as":[],"difficulty":"Intermediate","definition":"Historical volatility is a measure of how much an asset\'s price has actually fluctuated over a past period, usually calculated as the annualized standard deviation of its returns.","explanation":["Historical volatility looks backwards. It is calculated from past price data, typically daily returns over a period such as 30, 90 or 252 trading days, and is usually expressed as an annual percentage.","To annualize daily volatility, analysts commonly multiply it by the square root of the number of trading days in a year, often taken as 252. For example, a share whose daily returns have a standard deviation of 1% has an annualized historical volatility of about 16%.","Higher historical volatility means the asset\'s price has moved more, which indicates higher risk. Government bonds typically have low volatility, broad stock market indices moderate volatility, and individual shares, commodities and cryptocurrencies often much higher volatility.","Historical volatility is used in risk management, portfolio construction and option pricing. Traders often compare it with implied volatility. If implied volatility is much higher than historical volatility, options may look expensive relative to how much the asset has typically moved, although the market may be anticipating an event that past data does not reflect. Past volatility is not a guarantee of future volatility, which can change suddenly."],"note":"","total":1500,"prev":{"slug":"historical-cost","term":"Historical Cost"},"next":{"slug":"holding-period","term":"Holding Period"}}')}}]);